CREATE TABLE "billing_subscriptions" ("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL UNIQUE REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE,"provider" TEXT NOT NULL DEFAULT 'MANUAL' CHECK ("provider" IN ('MANUAL','STRIPE','IYZICO')),"providerCustomerId" TEXT,"state" TEXT NOT NULL DEFAULT 'TRIALING' CHECK ("state" IN ('TRIALING','ACTIVE','PAST_DUE','CANCELED')),"monthlyAmount" DECIMAL(12,2) NOT NULL DEFAULT 0,"currency" TEXT NOT NULL DEFAULT 'TRY',"dunningAttempt" INTEGER NOT NULL DEFAULT 0,"nextRetryAt" TIMESTAMP(3),"customUnitPrice" DECIMAL(12,2),"customPricingExpiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "billing_invoices" ("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE,"providerInvoiceId" TEXT UNIQUE,"amount" DECIMAL(12,2) NOT NULL,"currency" TEXT NOT NULL DEFAULT 'TRY',"status" TEXT NOT NULL DEFAULT 'OPEN' CHECK ("status" IN ('OPEN','PAID','FAILED','VOID')),"dueAt" TIMESTAMP(3) NOT NULL,"paidAt" TIMESTAMP(3),"failureReason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "billing_invoices_tenantId_createdAt_idx" ON "billing_invoices"("tenantId","createdAt");
CREATE TABLE "billing_provider_events" ("id" TEXT PRIMARY KEY,"provider" TEXT NOT NULL,"providerEventId" TEXT NOT NULL,"type" TEXT NOT NULL,"payload" JSONB NOT NULL,"processedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "billing_provider_events_provider_providerEventId_key" UNIQUE ("provider","providerEventId"));
CREATE TABLE "billing_coupons" ("id" TEXT PRIMARY KEY,"code" TEXT NOT NULL UNIQUE,"percent" INTEGER NOT NULL CHECK ("percent" BETWEEN 1 AND 100),"expiresAt" TIMESTAMP(3) NOT NULL,"maxRedemptions" INTEGER,"redemptionCount" INTEGER NOT NULL DEFAULT 0,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "subscription_discounts" ("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE,"couponId" TEXT NOT NULL REFERENCES "billing_coupons"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "subscription_discounts_tenantId_couponId_key" UNIQUE ("tenantId","couponId"));
CREATE INDEX "subscription_discounts_tenantId_expiresAt_idx" ON "subscription_discounts"("tenantId","expiresAt");
CREATE TABLE "custom_price_requests" ("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE,"monthlyAmount" DECIMAL(12,2) NOT NULL,"unitPrice" DECIMAL(12,2),"expiresAt" TIMESTAMP(3) NOT NULL,"reason" TEXT NOT NULL,"state" TEXT NOT NULL DEFAULT 'PENDING' CHECK ("state" IN ('PENDING','APPLIED','REJECTED')),"requestedById" TEXT NOT NULL,"decidedById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"decidedAt" TIMESTAMP(3));
CREATE INDEX "custom_price_requests_tenantId_createdAt_idx" ON "custom_price_requests"("tenantId","createdAt");
CREATE UNIQUE INDEX "custom_price_requests_one_pending" ON "custom_price_requests"("tenantId") WHERE "state" = 'PENDING';
